const contactForm=document.getElementById("contact-form");if(contactForm&&contactForm.dataset.configured==="true"){const e=document.getElementById("contact-form-status"),t=contactForm.querySelector('button[type="submit"]'),n=t.textContent;contactForm.addEventListener("submit",async s=>{s.preventDefault(),t.disabled=!0,t.textContent=contactForm.dataset.sending,e.textContent="",e.classList.remove("is-error","is-success");try{const t=await fetch(contactForm.action,{method:"POST",body:new FormData(contactForm),headers:{Accept:"application/json"}}),n=await t.json();if(!t.ok||n.success!==!0)throw new Error("Contact form submission failed");contactForm.reset(),e.textContent=contactForm.dataset.success,e.classList.add("is-success")}catch(t){console.error(t),e.textContent=contactForm.dataset.error,e.classList.add("is-error")}finally{t.disabled=!1,t.textContent=n}})}